from pathlib import Path
import re

p = Path('dashboard.html')
s = p.read_text()

new_overview = '''<section id="overview" class="section on"><div class="grid4"><div class="card"><div class="k">Monitored Accounts</div><div id="accounts" class="v">—</div></div><div class="card"><div class="k">Observed Members</div><div id="members" class="v">—</div></div><div class="card"><div class="k">Posts Analyzed</div><div id="overviewPosts" class="v">—</div></div><div class="card"><div class="k">Top Creative Score</div><div id="overviewTopScore" class="v">—</div><div id="overviewTopName" class="subv">—</div></div></div><div class="grid4"><div class="card"><div class="k">Active Links</div><div id="activeLinks" class="v">—</div><div id="activeLinksSub" class="subv">—</div></div><div class="card"><div class="k">Posts Analyzed · Last 24H</div><div id="posts24h" class="v">—</div><div id="posts24hSub" class="subv">Public posts in dataset</div></div><div class="card"><div class="k">Last Data Update</div><div id="lastDataUpdate" class="v" style="font-size:18px">—</div><div id="lastDataUpdateSub" class="subv">Latest successful source scrape</div></div><div class="card"><div class="k">Top Content Topic · 7D</div><div id="topTopic" class="v" style="font-size:18px">—</div><div id="topTopicSub" class="subv">—</div></div></div><div class="grid2"><div class="card"><div class="sectionHead"><h3>Audience Ranking</h3><span class="pill">LIVE</span></div><canvas id="audienceChart"></canvas></div><div class="card"><h3>What AI Learned</h3><div id="aiOverview"></div></div></div><div class="grid2"><div class="card"><div class="sectionHead"><div><h3>Active Monitored Links</h3><div class="muted small">Names and current monitoring status.</div></div><span id="activeLinksBadge" class="pill">—</span></div><div id="overviewSources" class="sourceList"><div class="muted">Loading active links…</div></div></div><div class="card"><div class="sectionHead"><div><h3>Trending Posts by Link</h3><div class="muted small">Top observed recent post from each monitored source, ranked by views.</div></div><span class="pill orange">7 DAYS</span></div><div id="overviewTrending"><div class="muted">Loading trending posts…</div></div></div></div><div class="card"><div class="sectionHead"><div><h3>Content Topic Analytics</h3><div class="muted small">Topic volume and observed view performance across the latest 7-day window.</div></div><span class="pill blue">CONTENT</span></div><div class="tableWrap"><table><thead><tr><th>Rank</th><th>Topic</th><th>Posts</th><th>Total Views</th><th>Avg Views</th><th>Share of Analyzed Posts</th></tr></thead><tbody id="topicBody"></tbody></table></div></div></section>'''
s = re.sub(r'<section id="overview" class="section on">.*?</section>\n<section id="growth"', new_overview + '\n<section id="growth"', s, count=1, flags=re.S)

new_render = r'''function renderOverview(){const ac=filterByHandle(allAccounts),cr=filterByHandle(allCreative),cut7=Date.now()-7*24*60*60*1000,cut24=Date.now()-24*60*60*1000,recent=cr.filter(r=>r.posted_at&&new Date(r.posted_at).getTime()>=cut7),recent24=cr.filter(r=>r.posted_at&&new Date(r.posted_at).getTime()>=cut24),src=selectedHandle()==='all'?allSources.filter(x=>x.is_active!==false):allSources.filter(x=>x.is_active!==false&&x.handle===selectedHandle());$('accounts').textContent=ac.length;$('members').textContent=compact(ac.reduce((sum,r)=>sum+(+r.followers_current||0),0));$('overviewPosts').textContent=cr.length;const top=[...cr].sort((a,b)=>Number(b.creative_score||0)-Number(a.creative_score||0))[0];$('overviewTopScore').textContent=top?Number(top.creative_score||0).toFixed(0):'—';$('overviewTopName').textContent=top?.account_name||'—';$('activeLinks').textContent=src.length;$('activeLinksSub').textContent=src.length?src.slice(0,3).map(x=>x.source_name||x.handle).join(' · ')+(src.length>3?` +${src.length-3} more`:''):'No active links';$('activeLinksBadge').textContent=src.length+' ACTIVE';$('posts24h').textContent=recent24.length;$('posts24hSub').textContent=recent24.length?`${new Set(recent24.map(x=>x.handle)).size} source(s) contributed`:'No posts observed in last 24h';const updates=src.map(x=>x.last_scraped_at).filter(Boolean).sort();const last=updates.length?updates[updates.length-1]:null;$('lastDataUpdate').textContent=last?dateFmt(last):'Waiting for scrape';$('lastDataUpdateSub').textContent=last?'Latest successful source scrape':'No successful scrape timestamp';const topics={};recent.forEach(r=>{const k=r.theme||'Unclassified',x=topics[k]||(topics[k]={topic:k,posts:0,views:0});x.posts++;x.views+=Number(r.views||0)});const topicRows=Object.values(topics).map(x=>({...x,avg:x.posts?x.views/x.posts:0})).sort((a,b)=>b.posts-a.posts||b.views-a.views);const tt=topicRows[0];$('topTopic').textContent=tt?.topic||'No topic data';$('topTopicSub').textContent=tt?`${tt.posts} posts · ${fmt.format(tt.views)} views observed`:'—';$('topicBody').innerHTML=topicRows.length?topicRows.slice(0,12).map((r,i)=>`<tr><td>#${i+1}</td><td><b>${esc(r.topic)}</b></td><td>${fmt.format(r.posts)}</td><td>${fmt.format(r.views)}</td><td>${fmt.format(Math.round(r.avg))}</td><td>${recent.length?((r.posts/recent.length)*100).toFixed(1):'0.0'}%</td></tr>`).join(''):'<tr><td colspan="6" class="muted">No topic data for this selection.</td></tr>';$('overviewSources').innerHTML=src.length?src.map(x=>`<div class="sourceRow"><div><b>${esc(x.source_name||x.handle||x.source_url)}</b><div class="muted small">${esc(x.handle||'')} · ${x.last_scraped_at?'Updated '+dateFmt(x.last_scraped_at):'Awaiting update'}</div></div><span class="pill ${x.scrape_status==='active'?'':'orange'}">${esc(x.scrape_status||'queued')}</span></div>`).join(''):'<div class="muted">No active monitored links for this selection.</div>';const bySource={};recent.forEach(r=>{const k=r.handle||r.account_name||'unknown';if(!bySource[k]||Number(r.views||0)>Number(bySource[k].views||0))bySource[k]=r});const trending=Object.values(bySource).sort((a,b)=>Number(b.views||0)-Number(a.views||0)).slice(0,9);$('overviewTrending').innerHTML=trending.length?trending.map((r,i)=>`<div class="aiItem"><div style="display:flex;justify-content:space-between;gap:10px"><b>#${i+1} ${esc(r.account_name||r.handle)}</b><span class="pill blue">${fmt.format(r.views||0)} views</span></div><div class="muted small" style="margin-top:5px">${esc(r.theme||'Unclassified')} · ${dateFmt(r.posted_at)}</div><div style="margin-top:6px">${esc((r.hook||r.post_text||'Media post').slice(0,120))}</div>${r.post_url?`<div style="margin-top:7px"><a target="_blank" rel="noopener" href="${esc(r.post_url)}">Open post ↗</a></div>`:''}</div>`).join(''):'<div class="muted">No recent posts available for trending analysis.</div>';if(audienceChart)audienceChart.destroy();audienceChart=new Chart($('audienceChart'),{type:'bar',data:{labels:ac.map(x=>x.account_name),datasets:[{data:ac.map(x=>x.followers_current),borderRadius:8}]},options:{plugins:{legend:{display:false}},scales:{x:{ticks:{color:'#8fa097'},grid:{display:false}},y:{ticks:{color:'#8fa097'},grid:{color:'#1c271f'}}}}});if(!cr.length){$('aiOverview').innerHTML='<div class="muted">No posts for this selection yet.</div>';return}const strongest=[...topicRows].sort((a,b)=>b.avg-a.avg)[0];$('aiOverview').innerHTML=`<div class="aiItem"><b>🔥 Top observed creative</b><div class="muted">${esc(top.account_name)} · ${fmt.format(top.views||0)} views · score ${Number(top.creative_score||0).toFixed(0)}</div></div><div class="aiItem"><b>📚 Most common topic</b><div class="muted">${esc(tt?.topic||'Unclassified')} across ${tt?.posts||0} recent posts.</div></div><div class="aiItem"><b>🚀 Highest-view topic</b><div class="muted">${esc(strongest?.topic||'—')} · ${strongest?fmt.format(Math.round(strongest.avg)):'—'} avg views.</div></div>`}'''
s = re.sub(r'function renderOverview\(\)\{.*?\}\nfunction renderGrowth\(\)', new_render + '\nfunction renderGrowth()', s, count=1, flags=re.S)

p.write_text(s)
print('overview v4 patched')
